START TRANSACTION;
ALTER TABLE pet_skills ADD COLUMN premium_locked BOOLEAN NOT NULL DEFAULT FALSE AFTER equipped;
CREATE TABLE player_home_badges(player_id BIGINT UNSIGNED NOT NULL,badge_code VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,owned BOOLEAN NOT NULL DEFAULT TRUE,equipped BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT UNSIGNED NOT NULL DEFAULT 1,updated_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(player_id,badge_code),CONSTRAINT fk_player_home_badge_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE hope_premium_delete_policy(policy_key VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,badge_code VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,intimacy_per_skill_slot BIGINT UNSIGNED NOT NULL,base_skill_slot_limit BIGINT UNSIGNED NOT NULL,textbook_slot_bonus BIGINT UNSIGNED NOT NULL,furniture_slot_bonus BIGINT UNSIGNED NOT NULL,PRIMARY KEY(policy_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO hope_premium_delete_policy VALUES('default','S13',100,30,3,3);
CREATE TABLE hope_premium_delete_operations(operation_id BIGINT UNSIGNED NOT NULL,operator_id BIGINT UNSIGNED NOT NULL,target_player_id BIGINT UNSIGNED NOT NULL,player_pet_id BIGINT UNSIGNED NOT NULL,locked_skill_count BIGINT UNSIGNED NOT NULL,removed_ticket_count BIGINT UNSIGNED NOT NULL,badge_revoked BOOLEAN NOT NULL,released_furniture_count BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(operation_id),CONSTRAINT fk_hope_delete_op FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE RESTRICT,CONSTRAINT fk_hope_delete_operator FOREIGN KEY(operator_id) REFERENCES admin_operators(id) ON DELETE RESTRICT,CONSTRAINT fk_hope_delete_player FOREIGN KEY(target_player_id) REFERENCES players(id) ON DELETE RESTRICT,CONSTRAINT fk_hope_delete_pet FOREIGN KEY(player_pet_id) REFERENCES player_pets(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE hope_premium_delete_skill_locks(operation_id BIGINT UNSIGNED NOT NULL,sequence_no INT UNSIGNED NOT NULL,player_pet_id BIGINT UNSIGNED NOT NULL,slot_no INT UNSIGNED NOT NULL,skill_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(operation_id,sequence_no),CONSTRAINT fk_hope_delete_lock_op FOREIGN KEY(operation_id) REFERENCES hope_premium_delete_operations(operation_id) ON DELETE RESTRICT,CONSTRAINT fk_hope_delete_lock_skill FOREIGN KEY(skill_id) REFERENCES skill_definitions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE hope_premium_delete_furniture_releases(operation_id BIGINT UNSIGNED NOT NULL,sequence_no INT UNSIGNED NOT NULL,placement_id BIGINT UNSIGNED NOT NULL,owned_furniture_id BIGINT UNSIGNED NOT NULL,placement_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,PRIMARY KEY(operation_id,sequence_no),CONSTRAINT fk_hope_delete_furniture_op FOREIGN KEY(operation_id) REFERENCES hope_premium_delete_operations(operation_id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('HOPE_PREMIUM_DELETE','hope_premium_delete','TRUSTED_DISPLAY_NAME','SHADOW',TRUE,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),rollout_state=VALUES(rollout_state),enabled=TRUE,version=version+1;
INSERT INTO command_aliases(command_text,command_code,active) VALUES('/호패프리미엄삭제','HOPE_PREMIUM_DELETE',TRUE) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=TRUE;
COMMIT;
